69	/*!
70	    \brief      initialize SPI0
71	    \param[in]  none
72	    \param[out] none
73	    \retval     none
74	*/
75	static void spi1_init(void)
76	{
77	    spi_parameter_struct spi_init_struct;
78	    rcu_periph_clock_enable(RCU_SPI);
79	    rcu_periph_clock_enable(RCU_GPIOA);
80	    rcu_periph_clock_enable(RCU_GPIOB);
81	
82	    /* configure SPI GPIO: SCK/PA11, MISO/PA10, MOSI/PA9 */
83	    gpio_af_set(GPIOA, GPIO_AF_0, GPIO_PIN_9 | GPIO_PIN_10 | GPIO_PIN_11);
84	    gpio_mode_set(GPIOA, GPIO_MODE_AF, GPIO_PUPD_NONE, GPIO_PIN_9 | GPIO_PIN_10 | GPIO_PIN_11);
85	    gpio_output_options_set(GPIOA, GPIO_OTYPE_PP, GPIO_OSPEED_25MHZ, GPIO_PIN_9 | GPIO_PIN_10 | GPIO_PIN_11);
86	
87	    /* configure GPIOB */
88	    gpio_mode_set(GPIOB, GPIO_MODE_OUTPUT, GPIO_PUPD_NONE, GPIO_PIN_12 | GPIO_PIN_13);
89	    gpio_output_options_set(GPIOB, GPIO_OTYPE_PP, GPIO_OSPEED_25MHZ, GPIO_PIN_12 | GPIO_PIN_13);
90	
91	    /* configure GPIOA */
92	    gpio_mode_set(GPIOA, GPIO_MODE_OUTPUT, GPIO_PUPD_NONE, GPIO_PIN_12);
93	    gpio_output_options_set(GPIOA, GPIO_OTYPE_PP, GPIO_OSPEED_25MHZ, GPIO_PIN_12);
94	
95	    /* configure SPI parameter */
96	    spi_init_struct.trans_mode           = SPI_TRANSMODE_FULLDUPLEX;
97	    spi_init_struct.device_mode          = SPI_MASTER;
98	    spi_init_struct.frame_size           = SPI_FRAMESIZE_8BIT;
99	    spi_init_struct.clock_polarity_phase = SPI_CK_PL_HIGH_PH_2EDGE;
100	    spi_init_struct.nss                  = SPI_NSS_SOFT;
101	    spi_init_struct.prescale             = SPI_PSC_4;
102	    spi_init_struct.endian               = SPI_ENDIAN_MSB;
103	    spi_init(&spi_init_struct);
104	
105	    /* set crc polynomial */
106	    spi_crc_polynomial_set(7);
107	    spi_enable();
108	}
