/****************************************************************************
 * Name: gd32_lcd_raw_test
 *
 * Description:
 *   Direct register access test - bypasses NuttX SPI driver entirely.
 *   Mimics the official GD32 demo exactly.
 *
 ****************************************************************************/

static uint8_t gd32_lcd_raw_spi_xfer(uint32_t spi_base, uint8_t tx)
{
  /* Wait TBE */
  while (!(getreg32(spi_base + 0x08) & (1 << 1)));
  putreg32(tx, spi_base + 0x0c);
  /* Wait RBNE */
  while (!(getreg32(spi_base + 0x08) & (1 << 0)));
  return (uint8_t)getreg32(spi_base + 0x0c);
}

static void gd32_lcd_raw_write_cmd(uint32_t spi_base, uint8_t cmd)
{
  /* DC low = command */
  putreg32((1 << 13), GD32VW55X_GPIOB_BASE + 0x14);  /* BC register, clear PB13 */
  gd32_lcd_raw_spi_xfer(spi_base, cmd);
  /* DC high = data */
  putreg32((1 << 13), GD32VW55X_GPIOB_BASE + 0x10);  /* BOP register, set PB13 */
}

static void gd32_lcd_raw_write_data(uint32_t spi_base, uint8_t data)
{
  gd32_lcd_raw_spi_xfer(spi_base, data);
}

void gd32_lcd_raw_test(void)
{
  uint32_t spi_base = GD32VW55X_SPI_BASE;
  uint8_t id1, id2, id3;

  syslog(LOG_NOTICE, "=== RAW SPI TEST START ===\n");

  /* Enable clocks: RCU_APB2EN bit5=SPI, RCU_AHB1EN bit0=GPIOA, bit1=GPIOB */
  /* RCU base = 0x40021000, APB2EN offset = 0x18, AHB1EN offset = 0x14 */
  putreg32(getreg32(0x40021000 + 0x18) | (1 << 5), 0x40021000 + 0x18);   /* SPI clock */
  putreg32(getreg32(0x40021000 + 0x14) | (1 << 0) | (1 << 1), 0x40021000 + 0x14); /* GPIOA+GPIOB */

  /* Configure PA9/PA10/PA11 as AF0 (SPI):
   * AFSEL1 (pins 8-15): clear bits for pins 9,10,11
   * GPIOA base = 0x40040000, AFSEL1 offset = 0x24
   */
  putreg32(getreg32(0x40040000 + 0x24) & ~((0xF << 4) | (0xF << 8) | (0xF << 12)),
           0x40040000 + 0x24);
  /* GPIOA CTL: pins 9,10,11 = AF mode (0b10) */
  /* CTL offset = 0x00, each pin uses 2 bits */
  uint32_t ctl = getreg32(0x40040000 + 0x00);
  ctl &= ~((3 << 18) | (3 << 20) | (3 << 22));
  ctl |= (2 << 18) | (2 << 20) | (2 << 22);
  putreg32(ctl, 0x40040000 + 0x00);
  /* GPIOA OMODE: pins 9,10,11 = push-pull (0) */
  putreg32(getreg32(0x40040000 + 0x04) & ~((1 << 9) | (1 << 10) | (1 << 11)),
