  id2 = gd32_lcd_raw_spi_xfer(spi_base, 0xFF);
  gd32_lcd_raw_write_cmd(spi_base, 0xDC);
  id3 = gd32_lcd_raw_spi_xfer(spi_base, 0xFF);

