/****************************************************************************
 * Name: gd32_lcd_raw_test
 *
 * Description:
 *   Direct register access test - bypasses NuttX SPI driver entirely.
 *   Mimics the official GD32 demo exactly.
 *
 ****************************************************************************/

static uint8_t gd32_lcd_raw_spi_xfer(uint32_t spi_base, uint8_t tx)
{
  /* Wait TBE */
  while (!(getreg32(spi_base + 0x08) & (1 << 1)));
  putreg32(tx, spi_base + 0x0c);
  /* Wait RBNE */
  while (!(getreg32(spi_base + 0x08) & (1 << 0)));
  return (uint8_t)getreg32(spi_base + 0x0c);
}

static void gd32_lcd_raw_write_cmd(uint32_t spi_base, uint8_t cmd)
{
  /* DC low = command */
  putreg32((1 << 13), GD32VW55X_GPIOB_BASE + 0x28);  /* BC register, clear PB13 */
  gd32_lcd_raw_spi_xfer(spi_base, cmd);
  /* DC high = data */
  putreg32((1 << 13), GD32VW55X_GPIOB_BASE + 0x18);  /* BOP register, set PB13 */
}

static void gd32_lcd_raw_write_data(uint32_t spi_base, uint8_t data)
{
  gd32_lcd_raw_spi_xfer(spi_base, data);
}

void gd32_lcd_raw_test(void)
{
  uint32_t spi_base = GD32VW55X_SPI_BASE;
  uint32_t rcu_base = GD32VW55X_RCU_BASE;
  uint8_t id1, id2, id3;

  syslog(LOG_NOTICE, "=== RAW SPI TEST START ===\n");

  /* Dump GPIO AFSEL and CTL for PA9/PA10/PA11 */

  syslog(LOG_NOTICE, "GPIOA AFSEL1: 0x%08x CTL: 0x%08x OMODE: 0x%08x OSPD: 0x%08x\n",
         getreg32(GD32VW55X_GPIOA_BASE + 0x24),
         getreg32(GD32VW55X_GPIOA_BASE + 0x00),
         getreg32(GD32VW55X_GPIOA_BASE + 0x04),
         getreg32(GD32VW55X_GPIOA_BASE + 0x08));
  syslog(LOG_NOTICE, "GPIOB CTL: 0x%08x\n",
         getreg32(GD32VW55X_GPIOB_BASE + 0x00));

  /* Dump SPI CTL0 before reconfiguration */

  syslog(LOG_NOTICE, "SPI CTL0 before: 0x%08x STAT: 0x%08x\n",
         getreg32(spi_base + 0x00), getreg32(spi_base + 0x08));

  /* Disable SPI first (required before changing CTL0) */

  putreg32(getreg32(spi_base + 0x00) & ~(1 << 6), spi_base + 0x00);

  /* Configure SPI: Mode 3, 8-bit, master, software NSS, PSC_4 */

  putreg32((1 << 0) | (1 << 1) | (1 << 2) | (1 << 9) | (1 << 3),
           spi_base + 0x00);
  putreg32(0, spi_base + 0x04);
  putreg32(getreg32(spi_base + 0x00) | (1 << 6), spi_base + 0x00);

  syslog(LOG_NOTICE, "SPI CTL0 after: 0x%08x STAT: 0x%08x\n",
         getreg32(spi_base + 0x00), getreg32(spi_base + 0x08));

  /* CS low */

  putreg32((1 << 12), GD32VW55X_GPIOA_BASE + 0x28);
  syslog(LOG_NOTICE, "CS low done, GPIOA OCTL: 0x%08x\n",
         getreg32(GD32VW55X_GPIOA_BASE + 0x14));

  /* Read LCD ID */

  gd32_lcd_raw_write_cmd(spi_base, 0xDA);
  id1 = gd32_lcd_raw_spi_xfer(spi_base, 0xFF);
  gd32_lcd_raw_write_cmd(spi_base, 0xDB);
  id2 = gd32_lcd_raw_spi_xfer(spi_base, 0xFF);
  gd32_lcd_raw_write_cmd(spi_base, 0xDC);
  id3 = gd32_lcd_raw_spi_xfer(spi_base, 0xFF);

  /* CS high */

  putreg32((1 << 12), GD32VW55X_GPIOA_BASE + 0x18);

  syslog(LOG_NOTICE, "=== RAW SPI TEST: ID1=0x%02x ID2=0x%02x ID3=0x%02x ===\n",
         id1, id2, id3);

  /* Re-enable SPI for NuttX driver */

  putreg32(getreg32(spi_base + 0x00) | (1 << 6), spi_base + 0x00);
}

